   506	        private static string StripPurlVersion(string purl)
   507	        {
   508	            var suffixIndex = purl.IndexOf('?', StringComparison.Ordinal);
   509	            if (suffixIndex < 0)
   510	            {
   511	                suffixIndex = purl.IndexOf('#', StringComparison.Ordinal);
   512	            }
   513	            var coreEnd = suffixIndex < 0 ? purl.Length : suffixIndex;
   514	            var schemeSeparator = purl.IndexOf('/', StringComparison.Ordinal);
   515	
   516	            if (schemeSeparator < 0 || schemeSeparator >= coreEnd) return purl;
   517	
   518	            var atIndex = purl.LastIndexOf('@', coreEnd - 1, coreEnd - schemeSeparator);
   519	            if (atIndex <= schemeSeparator) return purl;
   520	
   521	            return purl.Remove(atIndex, coreEnd - atIndex);
   522	        }
